package org.apache.commons.lang3.text.translate;

import java.io.*;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class NumericEntityUnescaper_translate_TriageGen2Test {

    private NumericEntityUnescaper unescaper;
    private StringWriter writer;

    @Before
    public void setUp() {
        unescaper = new NumericEntityUnescaper();
        writer = new StringWriter();
    }

    @Test
    public void testTranslate_NoMatch() throws IOException {
        int result = unescaper.translate("abc", 0, writer);
        assertEquals(0, result);
        assertEquals("", writer.toString());
    }

    @Test
    public void testTranslate_NotEntityStart() throws IOException {
        int result = unescaper.translate("a&b", 1, writer);
        assertEquals(0, result);
        assertEquals("", writer.toString());
    }

    @Test
    public void testTranslate_AmpersandAtEnd() throws IOException {
        int result = unescaper.translate("&", 0, writer);
        assertEquals(0, result);
        assertEquals("", writer.toString());
    }

    @Test
    public void testTranslate_DecimalEntity() throws IOException {
        // &#60; is '<'
        int result = unescaper.translate("&#60;", 0, writer);
        assertEquals(5, result);
        assertEquals("<", writer.toString());
    }

    @Test
    public void testTranslate_HexEntityLower() throws IOException {
        // &#x3c; is '<'
        int result = unescaper.translate("&#x3c;", 0, writer);
        assertEquals(6, result);
        assertEquals("<", writer.toString());
    }

    @Test
    public void testTranslate_HexEntityUpper() throws IOException {
        // &#X3C; is '<'
        int result = unescaper.translate("&#X3C;", 0, writer);
        assertEquals(6, result);
        assertEquals("<", writer.toString());
    }

    @Test
    public void testTranslate_SurrogatePairEntity() throws IOException {
        // &#x1F600; is 😀 (U+1F600)
        int result = unescaper.translate("&#x1F600;", 0, writer);
        assertEquals(8, result);
        assertEquals("😀", writer.toString());
    }

    @Test
    public void testTranslate_NumberFormatException_Decimal() throws IOException {
        // Invalid decimal digits
        int result = unescaper.translate("&#abc;", 0, writer);
        assertEquals(0, result);
        assertEquals("", writer.toString());
    }

    @Test
    public void testTranslate_NumberFormatException_Hex() throws IOException {
        // Invalid hex digits (if 'x' is present, it expects hex)
        // Note: the code uses parseInt(..., 16), so 'g' is invalid
        int result = unescaper.translate("&#xg;", 0, writer);
        assertEquals(0, result);
        assertEquals("", writer.toString());
    }

    @Test
    public void testTranslate_NoSemicolon() throws IOException {
        // The code contains a while loop: while(input.charAt(end) != ';')
        // If ';' is missing, it will throw StringIndexOutOfBoundsException 
        // based on the provided implementation logic.
        try {
            unescaper.translate("&#60", 0, writer);
        } catch (StringIndexOutOfBoundsException e) {
            // Expected behavior based on the provided code snippet
        }
    }

    @Test
    public void testTranslate_BoundaryDecimal() throws IOException {
        // Test entity value exactly at 0xFFFF boundary
        // &#65535;
        int result = unescaper.translate("&#65535;", 0, writer);
        assertEquals(7, result);
        // Character.toChars(0xFFFF) is just one char, but logic says:
        // if(entityValue > 0xFFFF) { write 2 chars } else { write 1 char }
        // So 65535 should write 1 char.
        assertEquals("\uFFFF", writer.toString());
    }
}
